-- GENERATED by `wfj generate` from data/gossip/gossip-1b.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["1b00cd678cf3e926"] = { "Siamo i discendenti degli Alti Nobili e nessuno ci fermerà!", "." },
  ["1b066b89b93e9ca5"] = { "Io fa te diventare mojo!", "." },
  ["1b0d839646b105c0"] = { "Sono giunti tempi bui, {class}... Troppo presto perderemo tutto... Quando la Luce abbandonerà tutti tranne coloro che camminano davvero sotto la Luce.", "." },
  ["1b0f21fc25332a4f"] = { "Insegnarti l'ingegneria degli gnomi? Non ho tempo per queste sciocchezze. Con Oglethorpe hai una sola possibilità e te la sei giocata, vero?\n\nDovrai andare a Tanaris e trovare la capanna di Narain Soothfancy. In quella capanna c'è un libro magico che potrebbe scuotere quel che resta del tuo cervello e ricollegarti a ciò che hai perso.\n\nOra sparisci!", "." },
  ["1b0f4bc27814316a"] = { "Da questo molo puoi trovare un passaggio per Theramore. Ascolta le mie parole: quelle terre sono di rado sicure per la gente dell'⟦Alliance=Alleanza⟧. Fai attenzione a dove metti i piedi e guardati le spalle.", "." },
  ["1b162d35fe3a28ad"] = { "Ehilà, {class}! Pare che abbiamo tutti i pinnagialla maculati che ci servono per quella guerra. Magari tu va da altri raccoglitori qui intorno e chiedi se loro hanno bisogno di tuo aiuto?", "." },
  ["1b17efe7e270f214"] = { "Korrak è arrivato, smidollati! Nevealta appartiene agli Asciafredda!", "." },
  ["1b1b7145736f34cf"] = { "Un test riuscito! {name}, questo indurio è roba straordinaria.", "." },
  ["1b207a30c9ff75f0"] = { "Abbi cura di te, Antonio. Ci vediamo tra una settimana.", "." },
  ["1b207c7ce0767697"] = { "Adesso l'hai fatta grossa. Credevo che fossi meglio della gente di ⟦Southshore=Riva del Sud⟧. Loro avrebbero comprato tutta la mia merce!", "." },
  ["1b243746509ea076"] = { "Ehi Reese, un altro giro per me e Christoph.", "." },
  ["1b304b812d2895cf"] = { "Grazie per l'aiuto, {name}. Ti auguro ogni bene nelle tue avventure.", "." },
  ["1b32b4bd69271044"] = { "Kazum! Possiedo il tuo scettro! Ti ordino di entrare in questo mondo!", "." },
  ["1b335a0c1d935927"] = { "Porta i miei saluti al comandante Trebor, {race}.", "." },
  ["1b3d62880bece4ba"] = { "La battaglia per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧ è una battaglia che non possiamo perdere. Combattiamo per il nostro onore e per la nostra terra, e nessun orco né alleato traviato ce li porterà via!", "." },
  ["1b5261271e50a5c0"] = { "Così si ragiona! Prendi ago e filo e diamoci dentro!", "." },
  ["1b5513f7c6d8ce32"] = { "%s sembra immerso in una profonda contemplazione.", "." },
  ["1b561d1b378f313b"] = { "<Mivin indica la sua merce e poi di nuovo te con un sorriso, ma non dice nulla.>", "." },
  ["1b5a78a1042418c6"] = { "Non sentiamo nulla. Le nostre anime restano qui, nel limbo. Non possiamo andarcene finché i nostri resti non saranno ritrovati e i nostri spiriti non avranno trovato pace.", "." },
  ["1b61f873e070e0af"] = { "<Il {race} davanti a te ondeggia malfermo, chiaramente molto ubriaco.>\n\nEro un marinaio, sai? Prima che cominciassero i guai. Gli skycutter facevano la spola tra le isole. Ora non è sicuro, o qualcosa del genere, così dicono.\n\nVedo che l'High Order e i Windshapers hanno rimesso in servizio i loro skycutter, ma io sono bloccato qui, a terra!\n\nCosa non ci stanno dicendo?!\n\n<Si volta e urla a gran voce verso il locandiere.>\n\nCOSA NON CI STANNO DICENDO, DONAAL?!", "." },
  ["1b676ced5da7944a"] = { "Prendi il ⟦Symbol of Life=Simbolo della Vita⟧ e usalo per resuscitare il guardiamorte Falgan nella ⟦Venomweb Vale=Valle Tela Venefica⟧.", "." },
  ["1b6e9f605c3bc5bd"] = { "Temo che tu sia fuori dalla mia portata, <amico/amica>! Dovresti andare da Nogg a Orgrimmar, ti porterà al livello successivo!", "." },
  ["1b70bbcd171f8e73"] = { "Fai scivolare qualche moneta nella mano del capo e guarda cosa ci guadagni. Adoro il mio lavoro. Però, se riuscissi a far trasferire in questo porto quella piccola peperina di Snurk... beh, non potrei immaginare niente di meglio. Ma scommetto che non sei qui per parlare dei miei metodi di lavoro. Stai cercando lo zeppelin per ⟦Undercity=Sepulcra⟧, dico bene? Ottimo, perché attracca proprio qui dietro di me. Ah, e senti, se vedi Snurk, metti una buona parola per me, d'accordo?", "." },
  ["1b7155bcd6bdf9c7"] = { "Tornerò quando avrò le Plates of Uldum.", "." },
  ["1b7da3291ab5a470"] = { "Cosa sono le Plates of Uldum?", "." },
  ["1b929c8f7b977a69"] = { "Dabu! Farò attenzione, papà!", "." },
  ["1b93753046837375"] = { "Non si fermerà davanti a nulla pur di raggiungere la manifestazione fisica di Malfurion. Non deve accadere... Dobbiamo tenere occupata la bestia abbastanza a lungo da permettere a Tyrande di arrivare.", "." },
  ["1b945388f31414af"] = { "Individueremo l'origine dell'Incubo grazie ai frammenti che hai raccolto, {name}. Da lì trascineremo Eranikus attraverso uno squarcio nel Sogno. Preparati, {class}. Stiamo invitando nel nostro mondo l'incarnazione stessa dell'Incubo.", "." },
  ["1b99480f5e33c78c"] = { "Coraggio!\n\nIl Soulflayer è stato sconfitto e il suo cuore immondo è stato scagliato nel Nether!", "." },
  ["1b9a823e5ca5d076"] = { "Uno di questi giorni lo affogo in quella tunica blu. E tutte le sue scope pure.", "." },
  ["1ba4f8d18110a00b"] = { "Questo è un posto pericoloso, {name}. Fai attenzione da queste parti.", "." },
  ["1bb9c4dfe3019937"] = { "Bene, {name}. Il tuo ritorno qui significa che sei davvero pront<o/a> per il passo successivo.\n\nDi tutti gli elementi, la terra rappresenta il fondamento di tutte le cose. È la tua forza, la tua resistenza e la tua pazienza. La Madre Terra ti proteggerà, ma solo se le mostrerai il giusto rispetto. Lei è la base della vita e, osservando le sue leggi, otterrai una saggezza più grande. Non dimenticare mai i segreti che condivide con te.\n\nOra preparerò per te la tua sapta e, accettandola, un nuovo sentiero si aprirà davanti a te.", "." },
  ["1bba15e717b75829"] = { "Misurata in Kraklenheit, sono 428.000 gradi! Questo sì che è Krakley!", "." },
  ["1bca03d1fa3e69f7"] = { "<Gli occhi di Cyrus brillano intensamente>\n\nTi divoro in un boccone o ti lascio vivere?\n\nForse potresti ancora tornarmi utile...\n\nSfida il mio servitore, {race}. Sopravvivi e riportami la prova della tua vittoria.", "." },
  ["1bcf8a14d92794f1"] = { "Proprio come ti avevo detto, vero?", "." },
  ["1bd0d51cbaf36fb3"] = { "Grazie.", "." },
  ["1bd233099378d05c"] = { "Ancora <vivo/viva>? Sai sorprendere. Guardami fuggire!", "." },
  ["1be279ed40c1f550"] = { "Che succede se faccio questo?!", "." },
  ["1be4545c159ed8a6"] = { "Salve, {name}! Io sono Scooty, maestro ingegnere.", "." },
  ["1be7c357cb0c01e4"] = { "Finalmente fuori da Northwatch Hold! Ho bisogno di un momento per riprendere fiato....", "." },
  ["1bec2b7812418866"] = { "Inginocchiati davanti a me, mortale! Inginocchiati davanti a Zod!", "." },
  ["1bef9508c8a891a4"] = { "La Stormpike Aid Station è stata presa dall'⟦Horde=Orda⟧!", "." },
  ["1bf6801c092f362e"] = { "Il coperchio del barile si svita lentamente.", "." },
  ["1bf78f0963165e8b"] = { "Comincerò ad attingere energia dalla pietra. Il tuo compito, {name}, è difendermi. Questo posto è maledetto... fidati.", "." },
})
